_cart_generic","n":"Food carts & stations","fn":"food_type","fv":"Crepe / pancake","fc":"food_cart","ic":"food_cart","s":false},{"f":"halo_halo_station","i":"food_cart_generic","n":"Food carts & stations","fn":"food_type","fv":"Halo-halo","fc":"food_cart","ic":"food_cart","s":false},{"f":"ice_cream_cart","i":"food_cart_generic","n":"Food carts & stations","fn":"food_type","fv":"Ice cream","fc":"food_cart","ic":"food_cart","s":false},{"f":"mini_lechon_station","i":"lechonero","n":"Lechon","fn":"format","fv":"Carving station","fc":"food_cart","ic":"catering","s":false},{"f":"sorbetes_cart","i":"food_cart_generic","n":"Food carts & stations","fn":"food_type","fv":"Sorbetes","fc":"food_cart","ic":"food_cart","s":false},{"f":"booth_360","i":"photo_booth","n":"Photo booth","fn":"booth_type","fv":"360","fc":"photo_booth","ic":"photo_booth","s":false},{"f":"gif_booth","i":"photo_booth","n":"Photo booth","fn":"booth_type","fv":"GIF","fc":"photo_booth","ic":"photo_booth","s":false},{"f":"polaroid_booth","i":"photo_booth","n":"Photo booth","fn":"booth_type","fv":"Polaroid / Instax","fc":"photo_booth","ic":"photo_booth","s":false},{"f":"selfie_magic_mirror","i":"photo_booth","n":"Photo booth","fn":"booth_type","fv":"Magic mirror","fc":"photo_booth","ic":"photo_booth","s":false},{"f":"perfume_bar","i":"massage_chair_station","n":"Pampering station","fn":"station_type","fv":"Perfume bar","fc":"perfume_bar","ic":"massage_chair","s":false},{"f":"vr_ar_station","i":"arcade_retro_games","n":"Games station","fn":"game_type","fv":"VR / AR","fc":"arcade_games","ic":"arcade_games","s":false},{"f":"mehndi_artist","i":"henna_tattoo_booth","n":"Henna / mehndi artist","fn":"style","fv":"Bridal mehndi","fc":"henna_tattoo","ic":"caricature_calligraphy_painting","s":false},{"f":"muslim_henna_artist","i":"henna_tattoo_booth","n":"Henna / mehndi artist","fn":"style","fv":"Muslim cultural","fc":"henna_tattoo","ic":"caricature_calligraphy_painting","s":false},{"f":"mini_nail_bar","i":"massage_chair_station","n":"Pampering station","fn":"station_type","fv":"Nail bar","fc":"mini_nail_bar","ic":"massage_chair","s":false},{"f":"palmistry_reader","i":"tarot_astrology","n":"Fortune reading","fn":"reading","fv":"Palmistry","fc":"tarot_astrology_palmistry","ic":"arcade_games","s":false},{"f":"live_calligraphy","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Calligraphy","fc":"caricature_calligraphy_painting","ic":"caricature_calligraphy_painting","s":false},{"f":"poetry_typewriter","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Poetry typewriter","fc":"caricature_calligraphy_painting","ic":"caricature_calligraphy_painting","s":false},{"f":"silhouette_artist","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Silhouette","fc":"caricature_calligraphy_painting","ic":"caricature_calligraphy_painting","s":false},{"f":"wedding_portrait_painter","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Live painting","fc":"caricature_calligraphy_painting","ic":"caricature_calligraphy_painting","s":false},{"f":"keychain_engraving","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Engraving","fc":"engraving_embroidery","ic":"caricature_calligraphy_painting","s":false},{"f":"live_embroidery","i":"caricature_artist","n":"Live artist (caricature, calligraphy, engraving)","fn":"art_type","fv":"Embroidery","fc":"engraving_embroidery","ic":"caricature_calligraphy_painting","s":false},{"f":"ceremony_program","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Programs","fc":"printing","ic":"printing","s":false},{"f":"invitation_digital","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Digital invitation","fc":"printing","ic":"printing","s":false},{"f":"menu_card","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Menu cards","fc":"printing","ic":"printing","s":false},{"f":"place_card","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Place cards","fc":"printing","ic":"printing","s":false},{"f":"save_the_date_digital","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Save-the-date","fc":"printing","ic":"printing","s":false},{"f":"stationery_signage","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Signage","fc":"printing","ic":"printing","s":false},{"f":"wedding_cards_designer","i":"invitation_print","n":"Invitations & stationery","fn":"item","fv":"Custom design","fc":"printing","ic":"printing","s":false},{"f":"angpao_betrothal_supplier","i":"souvenirs_giveaways","n":"Souvenirs & tokens","fn":"item","fv":"Ang pao / betrothal (Chinese)","fc":"souvenir_giveaways","ic":"souvenir_giveaways","s":false},{"f":"godchild_token","i":"souvenirs_giveaways","n":"Souvenirs & tokens","fn":"item","fv":"Inaanak tokens","fc":"souvenir_giveaways","ic":"souvenir_giveaways","s":false},{"f":"pasalubong_box","i":"souvenirs_giveaways","n":"Souvenirs & tokens","fn":"item","fv":"Pasalubong boxes","fc":"souvenir_giveaways","ic":"souvenir_giveaways","s":false},{"f":"sponsor_token","i":"souvenirs_giveaways","n":"Souvenirs & tokens","fn":"item","fv":"Sponsor tokens","fc":"souvenir_giveaways","ic":"souvenir_giveaways","s":false},{"f":"medals_plaques","i":"trophy_supplier","n":"Trophies, medals & plaques","fn":"item","fv":"Medals & plaques","fc":"trophies_awards","ic":"souvenir_giveaways","s":false},{"f":"bridal_boat_yacht","i":"transportation_bridal_car","n":"Bridal car","fn":"vehicle","fv":"Boat / yacht","fc":"bridal_car","ic":"bridal_car","s":false},{"f":"horse_drawn_carriage","i":"transportation_bridal_car","n":"Bridal car","fn":"vehicle","fv":"Horse carriage","fc":"bridal_car","ic":"bridal_car","s":false},{"f":"vintage_classic_vehicle","i":"transportation_bridal_car","n":"Bridal car","fn":"vehicle","fv":"Vintage / classic","fc":"bridal_car","ic":"bridal_car","s":false},{"f":"airport_transfer","i":"transportation_guest_shuttle","n":"Guest transport","fn":"vehicle","fv":"Airport transfer","fc":"transfers_rentals","ic":"guest_shuttle","s":false},{"f":"boat_ferry_charter","i":"transportation_guest_shuttle","n":"Guest transport","fn":"vehicle","fv":"Boat / ferry","fc":"transfers_rentals","ic":"guest_shuttle","s":false},{"f":"motorcycle_scooter_rental","i":"transportation_guest_shuttle","n":"Guest transport","fn":"vehicle","fv":"Motorcycle / scooter","fc":"transfers_rentals","ic":"guest_shuttle","s":false},{"f":"private_car_charter","i":"transportation_guest_shuttle","n":"Guest transport","fn":"vehicle","fv":"Private car","fc":"transfers_rentals","ic":"guest_shuttle","s":false},{"f":"van_rental","i":"transportation_guest_shuttle","n":"Guest transport","fn":"vehicle","fv":"Van","fc":"transfers_rentals","ic":"guest_shuttle","s":false},{"f":"tour_guide","i":"tour_activity","n":"Tours & activities","fn":"type","fv":"Tour guide","fc":"tour_guide","ic":"tour_activity","s":false},{"f":"personal_accident_insurance","i":"event_insurance","n":"Insurance","fn":"cover","fv":"Personal accident","fc":"personal_accident_insurance","ic":"event_insurance","s":false},{"f":"travel_insurance","i":"event_insurance","n":"Insurance","fn":"cover","fv":"Travel","fc":"travel_insurance","ic":"event_insurance","s":false},{"f":"embalming_preparation","i":"wake_package","n":"Funeral home & wake","fn":"includes","fv":"Embalming","fc":"funeral_home","ic":"funeral_home","s":false},{"f":"funeral_chapel","i":"wake_package","n":"Funeral home & wake","fn":"includes","fv":"Chapel / viewing","fc":"funeral_home","ic":"funeral_home","s":false},{"f":"urn","i":"casket","n":"Casket & urn","fn":"type","fv":"Urn","fc":"funeral_home","ic":"funeral_home","s":false},{"f":"columbarium_niche","i":"memorial_lot","n":"Resting place (lot, mausoleum, niche)","fn":"type","fv":"Columbarium niche","fc":"cremation","ic":"memorial_park","s":false},{"f":"mausoleum","i":"memorial_lot","n":"Resting place (lot, mausoleum, niche)","fn":"type","fv":"Mausoleum","fc":"memorial_park","ic":"memorial_park","s":false}]$map$::jsonb;
  v_tiles  JSONB := $map$[{"s":"ceremony_venue","d":"reception"},{"s":"counseling_seminars","d":"officiants"},{"s":"date_specialist","d":"coordinator"},{"s":"wedding_paperwork","d":"travel_honeymoon"},{"s":"stations","d":"food_cart"},{"s":"crew_meals","d":"catering"},{"s":"dance_floor","d":"lights_sound"},{"s":"outdoor","d":"chairs_tents"},{"s":"fireworks","d":"lights_sound"},{"s":"led_wall","d":"lights_sound"},{"s":"choir","d":"live_band"},{"s":"orchestra","d":"live_band"},{"s":"wedding_singer","d":"live_band"},{"s":"dj","d":"live_band"},{"s":"choreographer","d":"performers"},{"s":"av_production","d":"lights_sound"},{"s":"speaker_talent","d":"host_mc"},{"s":"kids_entertainer","d":"performers"},{"s":"womens_attire","d":"brides_attire"},{"s":"mens_attire","d":"grooms_attire"},{"s":"grooming","d":"hmua"},{"s":"shoes_footwear","d":"jewelleries_accessories"},{"s":"coffee_espresso","d":"mobile_bar"},{"s":"mocktail","d":"mobile_bar"},{"s":"food_truck","d":"food_cart"},{"s":"dessert","d":"food_cart"},{"s":"perfume_bar","d":"massage_chair"},{"s":"henna_tattoo","d":"caricature_calligraphy_painting"},{"s":"mini_nail_bar","d":"massage_chair"},{"s":"tarot_astrology_palmistry","d":"arcade_games"},{"s":"engraving_embroidery","d":"caricature_calligraphy_painting"},{"s":"trophies_awards","d":"souvenir_giveaways"},{"s":"escort","d":"bridal_car"},{"s":"transfers_rentals","d":"guest_shuttle"},{"s":"tour_guide","d":"tour_activity"},{"s":"personal_accident_insurance","d":"event_insurance"},{"s":"travel_insurance","d":"event_insurance"},{"s":"cremation","d":"memorial_park"},{"s":"editorial","d":"photo_video"},{"s":"filipiniana_barongs","d":"brides_attire"}]$map$::jsonb;
  v_labels JSONB := $map$[{"t":"reception","l":"Venues"},{"t":"officiants","l":"Officiants & seminars"},{"t":"accommodation","l":"Accommodation"},{"t":"coordinator","l":"Coordinator / Planner"},{"t":"travel_honeymoon","l":"Travel & paperwork"},{"t":"cake","l":"Cake"},{"t":"catering","l":"Catering"},{"t":"food_cart","l":"Food carts & stations"},{"t":"stylist_decorator","l":"Stylist / Decorator"},{"t":"florist","l":"Florist"},{"t":"lights_sound","l":"Lights, sound & effects"},{"t":"chairs_tents","l":"Rentals & outdoor"},{"t":"live_band","l":"Music"},{"t":"performers","l":"Entertainment & dance"},{"t":"host_mc","l":"Hosts & talent"},{"t":"photo_video","l":"Photo & Video"},{"t":"brides_attire","l":"Gowns & dresses"},{"t":"grooms_attire","l":"Barong & suits"},{"t":"hmua","l":"Hair, makeup & grooming"},{"t":"wellness_fitness","l":"Wellness & Fitness"},{"t":"jewelleries_accessories","l":"Jewellery, accessories & shoes"},{"t":"mobile_bar","l":"Bars & drinks"},{"t":"massage_chair","l":"Pampering stations"},{"t":"photo_booth","l":"Photo Booth"},{"t":"arcade_games","l":"Games & fortune-telling"},{"t":"caricature_calligraphy_painting","l":"Live artists & henna"},{"t":"printing","l":"Invitations & printing"},{"t":"souvenir_giveaways","l":"Souvenirs & awards"},{"t":"bridal_car","l":"Bridal car & escort"},{"t":"guest_shuttle","l":"Guest transport"},{"t":"tour_activity","l":"Tours & Activities"},{"t":"restaurant_reservation","l":"Restaurant (Reservation)"},{"t":"referee_official","l":"Referees / Officials"},{"t":"event_medic","l":"Medic / First-aid"},{"t":"event_insurance","l":"Insurance"},{"t":"reveal_element","l":"Reveal Element"},{"t":"funeral_home","l":"Funeral Home"},{"t":"memorial_park","l":"Cremation & memorial park"}]$map$::jsonb;
  r        JSONB;
  t        JSONB;
  v_res    JSONB;
  v_moved  JSONB := '{}'::jsonb;
  v_k      TEXT;
  v_v      JSONB;
  v_n      INT;
  v_retiled INT := 0;
  v_tiles_merged INT := 0;
  v_tiles_skipped INT := 0;
  v_trades_merged INT := 0;
  v_trades_skipped INT := 0;
  v_tagged INT := 0;
  v_facets_written INT := 0;
  v_facets_refused TEXT[] := ARRAY[]::text[];
  v_schemas_added INT := 0;
  v_renamed_tiles INT := 0;
  v_renamed_trades INT := 0;
  v_vendor UUID;
  v_type   TEXT;
  v_def    JSONB;
  v_opts   JSONB;
  v_min    JSONB;
  v_payload JSONB;
BEGIN
  -- ── 1 · prerequisites ────────────────────────────────────────────────────
  IF to_regprocedure('public.merge_service_category(text,text,uuid)') IS NULL THEN
    RAISE EXCEPTION 'taxonomy merge 2026-11-06: merge_service_category() is missing';
  END IF;
  IF to_regprocedure('public.merge_canonical_service(text,text,uuid)') IS NULL THEN
    RAISE EXCEPTION 'taxonomy merge 2026-11-06: merge_canonical_service() is missing';
  END IF;

  -- ── 2 · re-tile each map trade onto its approved category ────────────────
  FOR r IN SELECT * FROM jsonb_array_elements(v_rows) LOOP
    CONTINUE WHEN (r->>'s')::boolean;
    UPDATE canonical_service_taxonomy c
       SET tile_id = r->>'ic', folder_id = sc.parent_id, updated_at = NOW()
      FROM service_categories sc
     WHERE sc.id = r->>'ic' AND sc.tier = 2 AND sc.merged_into_category_id IS NULL
       AND c.canonical_service IN (r->>'f', r->>'i')
       AND c.tile_id IS DISTINCT FROM r->>'ic';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_retiled := v_retiled + v_n;
  END LOOP;

  -- ── 3 · merge each disappearing category into its destination ────────────
  FOR t IN SELECT * FROM jsonb_array_elements(v_tiles) LOOP
    IF NOT EXISTS (SELECT 1 FROM service_categories
                    WHERE id = t->>'s' AND tier = 2 AND merged_into_category_id IS NULL)
       OR NOT EXISTS (SELECT 1 FROM service_categories
                    WHERE id = t->>'d' AND tier = 2 AND merged_into_category_id IS NULL) THEN
      v_tiles_skipped := v_tiles_skipped + 1;   -- already merged, or absent here
      CONTINUE;
    END IF;
    v_res := public.merge_service_category(t->>'s', t->>'d', NULL);
    v_tiles_merged := v_tiles_merged + 1;
    FOR v_k, v_v IN SELECT * FROM jsonb_each(v_res->'moved') LOOP
      v_moved := jsonb_set(v_moved, ARRAY['tile:' || v_k],
        to_jsonb(COALESCE((v_moved->>('tile:' || v_k))::int, 0) + (v_v #>> '{}')::int));
    END LOOP;
  END LOOP;

  -- ── 4 · retire the hidden "Everything else" ──────────────────────────────
  -- STATUS ONLY, NO FORWARD. It holds no trade, and it is already hidden. It
  -- is still the code fallback for a couple's SELF-ADDED supplier (VendorCategory
  -- `misc` → `everything_else`, lib/shortlist-taxonomy.ts), and the taxonomy
  -- snapshot ignores `status`, so a self-added supplier filed there keeps
  -- rendering. A forward would have re-filed those suppliers into an arbitrary
  -- trade category; there is no right destination for "a supplier we could not
  -- name", so none is invented here.
  UPDATE service_categories
     SET status = 'retired', marketplace_hidden = TRUE
   WHERE id = 'everything_else' AND tier = 2 AND status IS DISTINCT FROM 'retired';

  -- ── 5 · rename each surviving category ───────────────────────────────────
  FOR t IN SELECT * FROM jsonb_array_elements(v_labels) LOOP
    UPDATE service_categories SET label_en = t->>'l'
     WHERE id = t->>'t' AND tier = 2 AND merged_into_category_id IS NULL
       AND label_en IS DISTINCT FROM t->>'l';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_renamed_tiles := v_renamed_tiles + v_n;
  END LOOP;

  -- ── 6 · every surviving trade has a schema row + its approved name ───────
  FOR r IN SELECT DISTINCT ON (e->>'i') e FROM jsonb_array_elements(v_rows) e
            WHERE NOT (e->>'s')::boolean LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy WHERE canonical_service = r->>'i');
    INSERT INTO canonical_service_schemas (canonical_service, display_name_en)
    VALUES (r->>'i', r->>'n')
    ON CONFLICT (canonical_service) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_schemas_added := v_schemas_added + v_n;
    UPDATE canonical_service_schemas
       SET display_name_en = r->>'n', updated_at = NOW()
     WHERE canonical_service = r->>'i' AND display_name_en IS DISTINCT FROM r->>'n';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_renamed_trades := v_renamed_trades + v_n;
  END LOOP;

  -- ── 7 · one facet per (survivor, filter name) ────────────────────────────
  -- Shape (iteration 0044): the definition lives in category_specific_attributes
  -- {key: {type, label, options[]}}, filter_facets lists the keys. A NEW facet is
  -- PREPENDED — lib/vendor-facets.ts keeps the first 6 selectable dimensions,
  -- and the absorbed names are how a couple finds what used to be a separate
  -- trade. `is_rental` is a yes/no, stored as a boolean field (the couple facet
  -- UI surfaces multi_select / enum only, so it is recorded, not yet a chip).
  FOR r IN
    SELECT jsonb_build_object(
             'i', e->>'i', 'fn', e->>'fn',
             'vals', jsonb_agg(DISTINCT e->>'fv'))
      FROM jsonb_array_elements(v_rows) e
     WHERE NOT (e->>'s')::boolean AND e->>'fn' IS NOT NULL
     GROUP BY e->>'i', e->>'fn'
  LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_schemas WHERE canonical_service = r->>'i');
    v_type := CASE WHEN r->>'fn' = 'is_rental' THEN 'boolean' ELSE 'multi_select' END;
    SELECT category_specific_attributes->(r->>'fn') INTO v_def
      FROM canonical_service_schemas WHERE canonical_service = r->>'i';

    IF v_def IS NOT NULL AND v_def->>'type' IS DISTINCT FROM v_type
       AND NOT (v_type = 'multi_select' AND v_def->>'type' = 'enum') THEN
      -- A field of another shape already owns this key: never overwrite it.
      v_facets_refused := v_facets_refused || ((r->>'i') || '.' || (r->>'fn') || ' (is ' || COALESCE(v_def->>'type', '?') || ')');
      CONTINUE;
    END IF;

    IF v_type = 'boolean' THEN
      v_def := COALESCE(v_def, jsonb_build_object('type', 'boolean', 'label', 'Rental'));
    ELSE
      SELECT COALESCE(jsonb_agg(o ORDER BY o), '[]'::jsonb) INTO v_opts
        FROM (SELECT DISTINCT o FROM (
                SELECT jsonb_array_elements_text(COALESCE(v_def->'options', '[]'::jsonb)) AS o
                UNION
                SELECT jsonb_array_elements_text(r->'vals')) u) d;
      v_def := COALESCE(v_def, jsonb_build_object(
                 'type', 'multi_select',
                 'label', upper(left(replace(r->>'fn', '_', ' '), 1)) || substr(replace(r->>'fn', '_', ' '), 2)))
               || jsonb_build_object('options', v_opts);
    END IF;

    UPDATE canonical_service_schemas s
       SET category_specific_attributes = s.category_specific_attributes || jsonb_build_object(r->>'fn', v_def),
           filter_facets = CASE
             WHEN s.filter_facets ? (r->>'fn') THEN s.filter_facets
             WHEN v_type = 'boolean' THEN s.filter_facets || to_jsonb(r->>'fn')
             ELSE to_jsonb(ARRAY[r->>'fn']) || s.filter_facets
           END,
           updated_at = NOW()
     WHERE s.canonical_service = r->>'i'
       AND (s.category_specific_attributes->(r->>'fn') IS DISTINCT FROM v_def
            OR NOT s.filter_facets ? (r->>'fn'));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_facets_written := v_facets_written + v_n;
  END LOOP;

  -- ── 8 · tag the shops, then merge the trades ─────────────────────────────
  -- The rows arrive SELF-ROWS FIRST (generator order): a survivor's own tag
  -- (pre_cana_seminar → faith Catholic) must land before any other trade's
  -- shops are folded into it, or a Muslim counselling shop would be tagged
  -- Catholic too.
  FOR r IN SELECT * FROM jsonb_array_elements(v_rows) LOOP
    CONTINUE WHEN (r->>'s')::boolean;
    -- A survivor's own row carries work only when it names a facet, and only
    -- before anything was folded into it (a re-run would otherwise tag the
    -- shops that arrived by merge with the survivor's own value).
    IF r->>'f' = r->>'i' AND (r->>'fn' IS NULL OR EXISTS (
         SELECT 1 FROM canonical_service_taxonomy WHERE merged_into = r->>'i')) THEN
      CONTINUE;
    END IF;
    -- A source already folded away (second run) has no holders left: skip.
    IF r->>'f' <> r->>'i' AND EXISTS (
         SELECT 1 FROM canonical_service_taxonomy
          WHERE canonical_service = r->>'f' AND merged_into IS NOT NULL) THEN
      v_trades_skipped := v_trades_skipped + 1;
      CONTINUE;
    END IF;
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy WHERE canonical_service = r->>'f')
              OR NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy
                              WHERE canonical_service = r->>'i' AND merged_into IS NULL);

    SELECT required_for_visibility->'minimum_fields' INTO v_min
      FROM canonical_service_schemas WHERE canonical_service = r->>'i';

    FOR v_vendor IN
      SELECT vendor_profile_id FROM vendor_coverages WHERE canonical_service = r->>'f'
      UNION SELECT vendor_profile_id FROM vendor_profiles WHERE services @> ARRAY[r->>'f']
      UNION SELECT vendor_profile_id FROM vendor_services WHERE category = r->>'f'
      UNION SELECT vendor_profile_id FROM vendor_service_attributes WHERE canonical_service = r->>'f'
    LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_schemas WHERE canonical_service = r->>'i');

      -- (a) the shop's survivor attribute row, with the absorbed trade's own
      --     attributes folded in (survivor wins a scalar clash; lists union).
      SELECT COALESCE(d.attribute_payload, '{}'::jsonb), COALESCE(src.attribute_payload, '{}'::jsonb)
        INTO v_payload, v_v
        FROM (SELECT 1) one
        LEFT JOIN vendor_service_attributes d
               ON d.vendor_profile_id = v_vendor AND d.canonical_service = r->>'i'
        LEFT JOIN vendor_service_attributes src
               ON src.vendor_profile_id = v_vendor AND src.canonical_service = r->>'f'
                  AND r->>'f' <> r->>'i';
      FOR v_k IN SELECT jsonb_object_keys(v_v) LOOP
        IF NOT v_payload ? v_k THEN
          v_payload := v_payload || jsonb_build_object(v_k, v_v->v_k);
        ELSIF jsonb_typeof(v_payload->v_k) = 'array' AND jsonb_typeof(v_v->v_k) = 'array' THEN
          v_payload := v_payload || jsonb_build_object(v_k,
            (SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb)
               FROM (SELECT jsonb_array_elements(v_payload->v_k) x
                     UNION SELECT jsonb_array_elements(v_v->v_k)) u));
        END IF;
      END LOOP;

      -- (b) the facet value this shop earned by holding the absorbed trade.
      IF r->>'fn' IS NOT NULL AND NOT ((r->>'i') || '.' || (r->>'fn')) = ANY (
           SELECT split_part(x, ' ', 1) FROM unnest(v_facets_refused) x) THEN
        IF r->>'fn' = 'is_rental' THEN
          v_payload := v_payload || jsonb_build_object('is_rental', TRUE);
        ELSE
          v_payload := v_payload || jsonb_build_object(r->>'fn',
            (SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb)
               FROM (SELECT jsonb_array_elements(
                              CASE WHEN jsonb_typeof(v_payload->(r->>'fn')) = 'array'
                                   THEN v_payload->(r->>'fn') ELSE '[]'::jsonb END) x
                     UNION SELECT to_jsonb(r->>'fv')) u));
        END IF;
      END IF;

      CONTINUE WHEN v_payload = '{}'::jsonb;   -- nothing to record for this shop
      INSERT INTO vendor_service_attributes AS a
             (vendor_profile_id, canonical_service, attribute_payload, meets_visibility_minimum)
      VALUES (v_vendor, r->>'i', v_payload,
              COALESCE((SELECT bool_and(
                          v_payload ? m AND v_payload->m NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb))
                          FROM jsonb_array_elements_text(
                                 CASE WHEN jsonb_typeof(v_min) = 'array' THEN v_min ELSE '[]'::jsonb END) m), TRUE))
      ON CONFLICT (vendor_profile_id, canonical_service) DO UPDATE
         SET attribute_payload = EXCLUDED.attribute_payload,
             meets_visibility_minimum = EXCLUDED.meets_visibility_minimum,
             updated_at = NOW()
       WHERE a.attribute_payload IS DISTINCT FROM EXCLUDED.attribute_payload;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_tagged := v_tagged + v_n;
    END LOOP;

    -- (c) fold the trade away — every trade holder moves, the source stays as
    --     a tombstone forwarding to the survivor.
    IF r->>'f' <> r->>'i' THEN
      v_res := public.merge_canonical_service(r->>'f', r->>'i', NULL);
      v_trades_merged := v_trades_merged + 1;
      FOR v_k, v_v IN SELECT * FROM jsonb_each(v_res->'moved') LOOP
        v_moved := jsonb_set(v_moved, ARRAY['trade:' || v_k],
          to_jsonb(COALESCE((v_moved->>('trade:' || v_k))::int, 0) + (v_v #>> '{}')::int));
      END LOOP;
    END IF;
  END LOOP;

  PERFORM set_config('setnayan.taxonomy_merge_2026_11_06', jsonb_build_object(
    'trades_retiled', v_retiled,
    'tiles_merged', v_tiles_merged,
    'tiles_skipped', v_tiles_skipped,
    'trades_merged', v_trades_merged,
    'trades_skipped', v_trades_skipped,
    'tiles_renamed', v_renamed_tiles,
    'trades_renamed', v_renamed_trades,
    'schemas_added', v_schemas_added,
    'facets_written', v_facets_written,
    'facets_refused', to_jsonb(v_facets_refused),
    'shops_tagged', v_tagged,
    'moved', v_moved)::text, false);
  RAISE NOTICE 'taxonomy merge 2026-11-06: %', current_setting('setnayan.taxonomy_merge_2026_11_06');
END
$merge$;
